    /** Human-readable vault name. */
    readonly vaultName: string;
    /** Underlying deposit asset symbol. */
    readonly asset: string;
    /** Current withdrawable value (shares x exchange rate). */
    readonly currentBalance: Amount;
    /** Current annualized percentage yield. */
